#include <bits/stdc++.h>
using namespace std;

int calculate(int n, int k, int s, long long t) {
    while (t % n != 0) {
        int direction = s < k ? 1 : -1;
        s = (s + n + direction * (int)(t % n)) % n;
        t--;
    }
    t /= n;
    vector<long long> visited(n, -1);
    for (long long remaining = t; remaining > 0; remaining--) {
        if (visited[s] != -1) {
            long long cycle = visited[s] - remaining;
            for (int i = 0; i < n; i++) {
                if (visited[i] != -1 && visited[i] <= visited[s] && visited[i] % cycle == 0) {
                    return i;
                }
            }
            assert(false);
        }
        visited[s] = remaining;
        for (int i = n - 1; i > 0; i--) {
            if (s < k) {
                s += i;
                if (s >= n) s -= n;
            } else {
                s -= i;
                if (s < 0) s += n;
            }
        }
    }
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k, s;
    long long t;
    cin >> n >> k >> s >> t;
    cout << calculate(n, k, s - 1, t) + 1 << "\n";
    return 0;
}

